import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        long[] points = new long[n];
        for (int i = 0; i < n; i++) points[i] = in.nextLong();
        String tokens = in.next();
        long score = 0;
        for (int i = 0; i < tokens.length(); i++) {
            if (tokens.charAt(i) != 'T') continue;
            score += points[i];
            if (i > 0 && tokens.charAt(i - 1) == 'T') score += 1; // adjacent TT pair, counted at its right end
        }
        System.out.println(score);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	r := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(r, &n)
	points := make([]int64, n)
	for i := range points {
		fmt.Fscan(r, &points[i])
	}
	var tokens string
	fmt.Fscan(r, &tokens)
	var score int64
	for i := 0; i < len(tokens); i++ {
		if tokens[i] != 'T' {
			continue
		}
		score += points[i]
		if i > 0 && tokens[i-1] == 'T' {
			score++ // adjacent TT pair, counted at its right end
		}
	}
	fmt.Println(score)
}
